<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Mail,Http,DB};
use App\Models\User;
class MarketingEmailSettingsTest extends TestCase {use RefreshDatabase;
 private function owner():void {$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));Mail::fake();Http::preventStrayRequests();config(['marketing.email_smtp_hosts'=>['smtp.example.test'],'marketing.email_connection_test_enabled'=>false]);}
 private function payload(int $version=0):array{return ['version'=>$version,'host'=>'smtp.example.test','port'=>587,'encryption'=>'tls','username'=>'mailer@example.test','password'=>'private-test-password','from_name'=>'Test store','from_address'=>'mailer@example.test','reply_to'=>'reply@example.test','minute_limit'=>10,'hour_limit'=>100,'day_limit'=>500,'unit_minor'=>2,'currency'=>'USD'];}
 public function test_save_is_private_encrypted_versioned_and_never_sends():void {$this->owner();$this->postJson('/admin/marketing/settings/email/data',$this->payload())->assertOk()->assertDontSee('private-test-password');$this->getJson('/admin/marketing/settings/email/data')->assertOk()->assertJsonPath('settings.verified',false)->assertDontSee('private-test-password');$this->assertStringNotContainsString('private-test-password',DB::table('store_settings')->where('key','like','marketing_email:%')->value('value'));$this->postJson('/admin/marketing/settings/email/data',$this->payload())->assertStatus(409);Mail::assertNothingSent();Http::assertNothingSent();}
 public function test_staff_cannot_read_connection_secrets_or_save_and_unsafe_host_is_rejected():void {$this->owner();$this->postJson('/admin/marketing/settings/email/data',array_replace($this->payload(),['host'=>'127.0.0.1']))->assertUnprocessable();$this->postJson('/admin/marketing/settings/email/data',$this->payload())->assertOk();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);$u->permissions()->create(['permission'=>'marketing.view']);$this->actingAs($u);$this->getJson('/admin/marketing/settings/email/data')->assertOk()->assertJsonMissingPath('settings.username')->assertJsonMissingPath('settings.host');$this->postJson('/admin/marketing/settings/email/data',$this->payload(1))->assertForbidden();$this->postJson('/admin/marketing/settings/email/check',['version'=>1])->assertForbidden();Mail::assertNothingSent();}
 public function test_fake_connection_verification_password_preservation_and_revision_reset():void {$this->owner();$s=app(\App\Services\Marketing\MarketingEmailSettings::class);$this->postJson('/admin/marketing/settings/email/data',$this->payload())->assertOk();$this->postJson('/admin/marketing/settings/email/check',['version'=>1])->assertStatus(409);config(['marketing.email_connection_test_enabled'=>true]);$this->mock(\App\Services\Marketing\MarketingSmtpProbe::class)->shouldReceive('check')->once()->withArgs(fn($v)=>$v['password']==='private-test-password')->andReturnNull();$this->postJson('/admin/marketing/settings/email/check',['version'=>1])->assertOk()->assertJsonPath('settings.verified',true);$this->assertTrue($s->ready(1));$this->postJson('/admin/marketing/settings/email/data',array_replace($this->payload(1),['password'=>'','username'=>'changed@example.test']))->assertOk()->assertJsonPath('settings.verified',false);$this->assertSame('private-test-password',$s->transport()['password']);$this->assertFalse($s->ready(1));Mail::assertNothingSent();}
 public function test_failed_connection_never_leaks_provider_exception():void {$this->owner();$this->postJson('/admin/marketing/settings/email/data',$this->payload())->assertOk();config(['marketing.email_connection_test_enabled'=>true]);$this->mock(\App\Services\Marketing\MarketingSmtpProbe::class)->shouldReceive('check')->once()->andThrow(new \RuntimeException('private-test-password smtp failure'));$this->postJson('/admin/marketing/settings/email/check',['version'=>1])->assertOk()->assertJsonPath('settings.check_result','connection_failed')->assertDontSee('private-test-password');$this->assertStringNotContainsString('smtp failure',DB::table('store_settings')->where('key','like','marketing_email:%')->value('value'));}
 public function test_attempt_reservations_obey_limits_and_do_not_change_order_mail():void {$this->owner();$s=app(\App\Services\Marketing\MarketingEmailSettings::class);$s->save(array_replace($this->payload(),['minute_limit'=>1]));$raw=$s->raw();$raw['verified_at']=now()->toIso8601String();\App\Models\StoreSetting::where('key',$s->key())->update(['value'=>json_encode($raw)]);$first=(string)\Illuminate\Support\Str::uuid();$this->assertTrue($s->reserve($first,1));$this->assertTrue($s->reserve($first,1));$this->assertFalse($s->reserve((string)\Illuminate\Support\Str::uuid(),1));$default=config('mail.default');$smtp=config('mail.mailers.smtp');$s->bindMailer();$this->assertSame($default,config('mail.default'));$this->assertSame($smtp,config('mail.mailers.smtp'));Mail::assertNothingSent();}
 public function test_page_reuses_crm_form_and_jw_brand_without_pool():void {$this->owner();$this->get('/admin/marketing/settings/email')->assertOk()->assertSee('SMTP Connection')->assertSee('Sending Limits')->assertSee('Email Readiness')->assertDontSee('Xenibox')->assertDontSee('Save Node');}
 public function test_current_route_cannot_exceed_1000_and_quota_does_not_reset_at_midnight():void {$this->owner();$this->postJson('/admin/marketing/settings/email/data',array_replace($this->payload(),['day_limit'=>1001]))->assertUnprocessable();$this->travelTo(\Carbon\Carbon::parse('2026-10-30 23:59:00'));$s=app(\App\Services\Marketing\MarketingEmailSettings::class);$s->save(array_replace($this->payload(),['minute_limit'=>1,'hour_limit'=>1,'day_limit'=>1]));$raw=$s->raw();$raw['verified_at']=now()->toIso8601String();\App\Models\StoreSetting::where('key',$s->key())->update(['value'=>json_encode($raw)]);$this->assertTrue($s->reserve((string)\Illuminate\Support\Str::uuid(),1));$this->travel(2)->minutes();$this->assertFalse($s->reserve((string)\Illuminate\Support\Str::uuid(),1));$this->travel(24)->hours();$this->assertTrue($s->reserve((string)\Illuminate\Support\Str::uuid(),1));Mail::assertNothingSent();}
 public function test_same_mailbox_reservation_is_shared_across_merchant_rows():void {$this->owner();$s=app(\App\Services\Marketing\MarketingEmailSettings::class);$s->save(array_replace($this->payload(),['minute_limit'=>1]));$raw=$s->raw();$raw['verified_at']=now()->toIso8601String();\App\Models\StoreSetting::where('key',$s->key())->update(['value'=>json_encode($raw)]);DB::table('marketing_email_send_reservations')->insert(['delivery_id'=>(string)\Illuminate\Support\Str::uuid(),'merchant_key'=>'another-store','quota_key'=>$s->quotaKey($raw),'created_at'=>now()]);$this->assertFalse($s->reserve((string)\Illuminate\Support\Str::uuid(),1));Mail::assertNothingSent();}
}
